import { test, expect } from '@playwright/test';

test.describe('Data Refresh After Mutation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/data-table');
  });

  test('should refresh data automatically after a successful mutation', async ({ page }) => {
    // Verify initial data is displayed
    const tableBody = page.getByRole('row', { name: /data row/i });
    await expect(tableBody).toBeVisible();
    const initialRowCount = await page.getByRole('row').count();
    expect(initialRowCount).toBeGreaterThan(0);

    // Perform mutation (delete an item)
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await deleteButton.click();

    // Wait for API response and data refresh
    await page.waitForResponse(response => 
      response.url().includes('/api/data') && response.status() === 200
    );

    // Verify data has been refreshed
    const updatedRowCount = await page.getByRole('row').count();
    expect(updatedRowCount).toBeLessThan(initialRowCount);

    // Verify success message is displayed
    const successMessage = page.getByText(/item deleted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the deleted item is no longer in the table
    const deletedItemRow = page.getByRole('row', { name: /deleted item/i });
    await expect(deletedItemRow).not.toBeVisible();
  });

  test('should handle mutation failure and not refresh data', async ({ page }) => {
    // Intercept the mutation API call and simulate failure
    await page.route('**/api/data', route => {
      route.abort('failed');
    });

    // Verify initial data is displayed
    const tableBody = page.getByRole('row', { name: /data row/i });
    await expect(tableBody).toBeVisible();
    const initialRowCount = await page.getByRole('row').count();
    expect(initialRowCount).toBeGreaterThan(0);

    // Perform mutation (update an item)
    const updateButton = page.getByRole('button', { name: /update/i });
    await updateButton.click();

    // Wait for API response (which will fail)
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByText(/failed to update item/i);
    await expect(errorMessage).toBeVisible();

    // Verify data has NOT been refreshed (row count remains the same)
    const updatedRowCount = await page.getByRole('row').count();
    expect(updatedRowCount).toBe(initialRowCount);

    // Verify the original item is still visible
    const originalItemRow = page.getByRole('row', { name: /original item/i });
    await expect(originalItemRow).toBeVisible();
  });
});
